runs = {}
foreach scoreRow in matchRows {
    player = scoreRow.Player
    if (isKey(runs,player)) {
        runs[player] = runs[player] + scoreRow.Runs
    }
    else {
        runs[player] = scoreRow.Runs
    }
}

Procedure manualIsKey(D,k)
    found = False
    foreach candidate in keys(D) {
        if (candidate == k) {
            found = True
            exitloop
        }
    }
    return(found)
End manualIsKey

