profile = {}
foreach bill in bills {
    customer = bill.Customer
    if (not isKey(profile,customer)) {
        profile[customer] = {}
    }
    foreach item in bill.Items {
        category = broadCategory(item.Category)
        if (not isKey(profile[customer],category)) {
            profile[customer][category] = 0
        }
        profile[customer][category] = profile[customer][category] + 1
    }
}

Procedure distance(A,B)
    total = 0
    foreach category in categories {
        total = total + abs(A[category] - B[category])
    }
    return(total)
End distance

foreach i in [1,2,3,4,5,6] {
    foreach j in [1,2,3,4,5,6] {
        if (i < j) {
            record(i,j,distance(profile[i],profile[j]))
        }
    }
}

foodD = {}
foreach bill in bills {
    customer = bill.Customer
    foreach item in bill.Items {
        if (broadCategory(item.Category) == "Food") {
            if (isKey(foodD,customer)) {
                foodD[customer] = foodD[customer] + 1
            }
            else {
                foodD[customer] = 1
            }
        }
    }
}

billsByCustomer = {}
billByID = {}
foreach bill in bills {
    customer = bill.Customer
    if (not isKey(billsByCustomer,customer)) {
        billsByCustomer[customer] = []
    }
    billsByCustomer[customer] = billsByCustomer[customer] ++ [bill.BillNo]
    billByID[bill.BillNo] = bill
}
foreach id in billsByCustomer["Ahmed"] {
